<script setup lang="ts">
import { t } from '../i18n'
import { computed } from 'vue'
import type { SearchState } from '../types/search'
import { assessmentProtocol, decisionScore, protocolLabel } from '../utils/decisionOverview'
import AssessmentPlot from './AssessmentPlot.vue'

const props = defineProps<{ state: SearchState }>()
const emit = defineEmits<{ navigate: [view: string, candidateId?: string, axis?: string] }>()
const candidates = computed(() => props.state.candidates ?? [])
const selected = computed(() => candidates.value.find(c => c.id === props.state.selected_candidate_id))
const scored = computed(() => candidates.value.filter(c => decisionScore(props.state, c) !== null))
const actions = computed(() => (props.state.actions ?? []).filter(a => a.action !== 'model_decision' || !['completed', 'succeeded'].includes(a.status)))
const selectedAction = computed(() => [...actions.value].reverse().find(a => a.candidate_id === selected.value?.id))
const recipe = computed(() => props.state.registry?.find(r => r.id === selected.value?.id))
const recent = computed(() => actions.value.slice(-4))
const panel = computed(() => typeof props.state.panel === 'object' ? props.state.panel : null)
const pct = (value: number | null) => value === null ? t('No complete primary score') : `${(value * 100).toFixed(2)}%`
const series = computed(() => [{ get name() { return t('Primary score') }, connect: false, points: candidates.value.map((c, i) => ({ x: i + 1, y: decisionScore(props.state, c), label: `${c.title || c.id} · ${protocolLabel(props.state, c)}` })) }])
const statusLabel = (s: string) => ({ get interrupted() { return t('Interrupted') }, get evaluated() { return t('Evaluated') }, get completed() { return t('Completed') }, get running() { return t('Running') }, get pending() { return t('Pending') }, get failed() { return t('Failed') }, get execution_failure() { return t('Execution failed') }, get resource_failure() { return t('Insufficient resources') }, get evaluating() { return t('Evaluating') }, get proposed() { return t('Proposed') }, get rejected() { return t('Rejected') }, get skipped() { return t('Skipped') }, get succeeded() { return t('Completed') }, get cancelled() { return t('Cancelled') }, get unavailable() { return t('Cannot verify') }, get matched() { return t('Matches prediction') }, get contradicted() { return t('Contradicts prediction') } }[s] || s)
const actionLabel = (s: string) => ({ get initial_schedule() { return t('Schedule starting methods') }, get propose_candidate() { return t('Propose a candidate') }, get request_evidence() { return t('Gather evidence') }, get finish() { return t('End search') }, get model_decision() { return t('Choose next action') }, get invalid_proposal() { return t('Reject invalid proposal') } }[s] || s)
const steps = [
  { get title() { return t('Inspect signals') }, get text() { return t('Power spectra, amplitude, and channel correlations at each stage.') }, view: 'assessment', axis: 'quality', get link() { return t('View signal plots') } },
  { get title() { return t('Understand the method') }, get text() { return t('Processing order, parameters, and step execution.') }, view: 'assessment', axis: 'parameters', get link() { return t('View processing and parameters') } },
  { get title() { return t('Compare performance') }, get text() { return t('Model performance, subject variability, and evaluation coverage.') }, view: 'assessment', axis: 'utility', get link() { return t('View metrics and coverage') } },
  { get title() { return t('Trace decisions') }, get text() { return t('Proposal rationale, competing explanations, and prediction checks.') }, view: 'rounds', axis: undefined, get link() { return t('View full decision history') } },
]
</script>

<template>
  <section class="decision-overview" :aria-label="t('Decision overview')">
    <header class="overview-heading"><div><h2>{{ t('Preprocessing results') }}</h2></div><span class="scope">{{ t('Development evaluation') }}</span></header>
    <div class="decision-result">
      <div><span class="kicker">{{ state.selected_candidate_id ? t('Selected method') : t('Selection status') }}</span><h3>{{ selected?.title || state.selected_candidate_id || t('No method selected') }}</h3><p v-if="!state.selected_candidate_id">{{ t('Candidate evaluation is in progress. No final selection yet.') }}</p><p v-if="!['completed','stopped'].includes(state.status)" class="limit">{{ t('The search is incomplete. Available results are shown below.') }}</p></div>
      <div class="primary-score"><strong>{{ selected ? pct(decisionScore(state, selected)) : '—' }}</strong><span>{{ protocolLabel(state, selected) }}</span><small>{{ t('{0} / {1} candidates have a primary score', { 0: scored.length, 1: candidates.length }) }}</small></div>
    </div>
    <div class="evidence-route"><article v-for="(step, i) in steps" :key="step.title"><span class="step-number">0{{ i+1 }}</span><h3>{{ step.title }}</h3><p>{{ step.text }}</p><button @click="emit('navigate', step.view, selected?.id, step.axis)">{{ step.link }} →</button></article></div>
    <section class="overview-section"><h3>{{ t('Scoring rules and scope') }}</h3><p v-if="assessmentProtocol(state, selected) === 'eegnet'">{{ t('Primary score: the equal-weight mean of subject-macro BA for EEGNet seeds 17, 42, and 2026. All three seeds must complete. CSP-LDA is the benchmark.') }}</p><p v-else-if="assessmentProtocol(state, selected) === 'legacy-suite'">{{ t('Legacy score: the equal-weight mean of subject-macro BA for CSP-LDA, FBCSP, and TS-LR.') }}</p><p v-else>{{ t('The evaluator and primary score appear above. See run parameters for the full configuration.') }}</p><p v-if="['highest_complete_eegnet_three_seed_utility','highest_complete_three_learner_utility'].includes(String(state.protocol?.selection))">{{ t('Select the candidate with the highest complete primary score.') }}<template v-if="Array.isArray(state.protocol?.tie_break)">{{ t('Break exact ties in this order: {0}.', { 0: state.protocol.tie_break.map((key: string) => ({reference: t('Reference method first'),fewer_operators: t('Fewer operators first'),candidate_id: t('Candidate ID order')}[key] || key)).join(' → ') }) }}</template></p><p>{{ t('Development results guide candidate selection; generalization requires independent testing. Signal-quality metrics support diagnosis.') }}</p><p v-if="panel">{{ t('Scope: {0} development subjects · {1} eligible trials · {2} outer folds.', { 0: panel.development_subjects?.length ?? t('Not recorded'), 1: panel.eligible_count ?? t('Not recorded'), 2: panel.folds?.length ?? t('Not recorded') }) }}</p><p v-if="typeof state.panel === 'string'">{{ t('Evaluation scope: {0}', { 0: state.panel }) }}</p><p v-if="!panel && !state.panel">{{ t('Evaluation scope was not recorded.') }}</p><p v-if="selected?.receipt?.representation?.transductive">{{ t('This method adapts using the target subject\'s entire unlabeled batch under an offline transductive protocol. Deployment requires the same information access.') }}</p></section>
    <section v-if="selected" class="overview-section"><h3>{{ t('Selected processing sequence') }}</h3><ol v-if="recipe" class="recipe"><li v-for="node in recipe.recipe.nodes" :key="node.id"><strong>{{ state.protocol?.space?.operators.find(o => o.id === node.operator)?.title || node.operator }}</strong><span v-for="(value, key) in node.parameters" :key="key">{{ key }} = {{ value }}</span></li></ol><p v-else>{{ t('Processing order was not recorded.') }}</p><p v-if="recipe" class="muted">{{ t('See execution and parameters for per-record details.') }}</p><p v-if="selectedAction?.reason"><strong>{{ t('Proposal rationale:') }}</strong>{{ selectedAction.reason }}</p><p v-else class="muted">{{ t('Proposal rationale was not recorded.') }}</p><button @click="emit('navigate', 'assessment', selected.id, 'parameters')">{{ t('View execution and parameters →') }}</button></section>
    <section class="overview-section"><h3>{{ t('Candidate comparison') }}</h3><AssessmentPlot v-if="scored.length" :title="t('Candidate primary scores')" :series="series" :x-label="t('Candidate index (record order)')" :y-label="t('Development BA (0–1)')" :y-domain="[0,1]" :reference=".5" :caption="t('Each point is a candidate\'s development primary score, in record order. Unscored candidates are omitted; the dashed line marks BA=0.5.')" :provenance="{ search_id: state.id, protocol: state.protocol?.assessment || state.protocol?.evaluator, selected_candidate_id: state.selected_candidate_id }" /><ul class="candidate-list"><li v-for="candidate in candidates" :key="candidate.id"><div><strong>{{ candidate.title || candidate.id }}</strong><small>{{ statusLabel(candidate.status) }}<template v-if="candidate.id === state.selected_candidate_id">{{ t('· Selected') }}</template></small><details v-if="candidate.error" class="limit"><summary>{{ t('Failure or interruption reason') }}</summary><p>{{ candidate.error }}</p></details></div><span>{{ pct(decisionScore(state, candidate)) }}</span><button @click="emit('navigate', 'assessment', candidate.id, 'utility')">{{ t('View evidence →') }}</button></li></ul><p v-if="!candidates.length">{{ t('No candidate results yet.') }}</p></section>
    <section class="overview-section"><div class="section-heading"><h3>{{ t('Recent decisions and checks') }}</h3><button @click="emit('navigate', 'rounds')">{{ t('All {0} records →', { 0: actions.length }) }}</button></div><p v-if="!recent.length">{{ t('No decisions recorded yet.') }}</p><article v-for="action in recent" :key="action.index" class="decision-card"><small>{{ t('Record {0} · {1}', { 0: action.index, 1: statusLabel(action.status) }) }}</small><h4>{{ actionLabel(action.action) }}</h4><p>{{ action.reason || t('No explanation provided.') }}</p><template v-if="action.request?.hypothesis"><p><strong>{{ t('Hypothesis:') }}</strong>{{ action.request.hypothesis.explanation }}</p><p><strong>{{ t('Competing explanation:') }}</strong>{{ action.request.hypothesis.competing_explanation }}</p></template><ul v-if="action.result?.prediction_checks"><li v-for="(check,i) in action.result.prediction_checks.checks" :key="i">{{ check.explanation || check.metric }} — {{ statusLabel(check.status) }}<small>{{ check.metric }} · {{ check.before ?? t('Unavailable') }} → {{ check.after ?? t('Unavailable') }}</small></li></ul><p v-else class="muted">{{ t('No prediction checks available yet.') }}</p><details v-if="action.error" class="limit"><summary>{{ t('View failure or rejection reason') }}</summary><p>{{ action.error }}</p></details><button v-if="action.candidate_id" @click="emit('navigate', 'assessment', action.candidate_id, 'utility')">{{ t('View related candidate →') }}</button></article><p class="muted">{{ t('A matching prediction means the recorded measurement direction agrees with the expectation. It does not by itself establish a mechanism or causality.') }}</p></section>
    <footer><span>{{ t('Reports, models, and original records') }}</span><button @click="emit('navigate', 'artifacts')">{{ t('Open reports and files →') }}</button></footer>
  </section>
</template>

<style scoped>
.decision-overview{color:#28433e;font-size:14px;line-height:1.8}.overview-heading{display:flex;justify-content:space-between;gap:20px;align-items:start}.overview-heading h2{font-size:26px;margin:4px 0;font-weight:600}.overview-heading p{margin:0;color:#5c7470}.eyebrow,.kicker{font-size:12px;color:#34796e;letter-spacing:.06em}.scope{font-size:12px;white-space:nowrap;border:1px solid #d1dfd9;border-radius:20px;padding:4px 12px}.decision-result{display:grid;grid-template-columns:1.4fr 1fr;gap:28px;background:#eff6f3;border:1px solid #d6e6df;border-radius:14px;padding:24px;margin:24px 0}.decision-result h3{font-size:21px;margin:5px 0}.decision-result p{margin:4px 0;color:#516e63}.primary-score{border-left:1px solid #d1e1d8;padding-left:24px;display:flex;flex-direction:column;justify-content:center}.primary-score strong{font-size:30px;font-weight:600;color:#246b57}.primary-score span,.primary-score small{font-size:12px;color:#526e64}.evidence-route{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.evidence-route article{display:flex;flex-direction:column;border:1px solid #e0e7e5;border-radius:10px;padding:18px;background:#fff}.step-number{font-size:12px;color:#689288}.evidence-route h3{margin:4px 0}.evidence-route p{font-size:13px;color:#5e756c;margin:6px 0 18px;flex:1}button{font:inherit;font-size:12px;cursor:pointer;border:1px solid #cbdcd3;border-radius:6px;background:#fff;color:#236951;padding:7px 11px;text-align:left}button:hover{background:#edf5f0}button:focus-visible{outline:2px solid #367963;outline-offset:3px}.overview-section{padding-top:26px;margin-top:26px;border-top:1px solid #e0e7e4}.overview-section h3{font-size:17px;margin:0 0 12px}.overview-section p{margin:8px 0}.recipe{display:flex;flex-wrap:wrap;gap:12px;padding-left:22px}.recipe li{padding:10px 16px;background:#f4f7f6;border-radius:8px}.recipe span,.candidate-list small,.decision-card small{display:block;font-size:12px;color:#5e756c}.candidate-list{list-style:none;padding:0}.candidate-list li{display:flex;align-items:center;gap:20px;justify-content:space-between;padding:16px 0;border-bottom:1px solid #edf1ee}.candidate-list li>div{flex:1}.candidate-list li>span{font-variant-numeric:tabular-nums}.muted{color:#637b70;font-size:13px}.limit{color:#8b6032!important;overflow-wrap:anywhere;max-height:160px;overflow:auto}.section-heading,footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.decision-card{padding:18px 20px;border-left:3px solid #8cb5a7;background:#f7f9f8;margin:14px 0;overflow-wrap:anywhere}.decision-card h4{margin:4px 0;font-size:15px}footer{padding:20px;background:#f0f5f2;border-radius:10px;margin-top:28px;font-size:13px}@media(max-width:1100px){.evidence-route{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.decision-result{grid-template-columns:1fr;padding:18px;gap:16px}.primary-score{border-left:0;border-top:1px solid #d1e1d8;padding:14px 0 0}.evidence-route{grid-template-columns:1fr}.candidate-list li,footer{flex-wrap:wrap}.candidate-list li>div{flex-basis:100%}.overview-heading h2{font-size:22px}}
</style>
